def _comps(grid):
    h=len(grid); w=len(grid[0])
    seen=[[False]*w for _ in range(h)]
    out=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=0 and not seen[i][j]:
                c=grid[i][j]; st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    x,y=st.pop(); cells.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            nx,ny=x+dx,y+dy
                            if 0<=nx<h and 0<=ny<w and not seen[nx][ny] and grid[nx][ny]==c:
                                seen[nx][ny]=True; st.append((nx,ny))
                out.append((c,cells))
    return out

def transform(grid):
    cs=_comps(grid)
    h=len(grid); w=len(grid[0])
    bg=[[grid[i][j]==0 for j in range(w)] for i in range(h)]
    reach=[[False]*w for _ in range(h)]
    st=[]
    for i in range(h):
        for j in range(w):
            if (i==0 or i==h-1 or j==0 or j==w-1) and bg[i][j]:
                reach[i][j]=True; st.append((i,j))
    while st:
        x,y=st.pop()
        for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
            nx,ny=x+dx,y+dy
            if 0<=nx<h and 0<=ny<w and bg[nx][ny] and not reach[nx][ny]:
                reach[nx][ny]=True; st.append((nx,ny))
    enclosed=set((i,j) for i in range(h) for j in range(w) if bg[i][j] and not reach[i][j])
    for c,cells in cs:
        for (x,y) in cells:
            for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                if (x+dx,y+dy) in enclosed:
